def transform(g):
    h,w=len(g),len(g[0])
    out=[[0]*w for _ in range(h)]
    cov=[[set() for _ in range(w)] for _ in range(h)]
    cells=[(r,c,v) for r in range(h) for c in range(w) if (v:=g[r][c])]
    def mark(r,c,shape,val):
        if 0<=r<h and 0<=c<w:
            out[r][c]=val; cov[r][c].add(shape)
    for r,c,v in cells:
        if v==2:
            for i,cc in enumerate(range(c-4,c+1)):
                mark(r,cc,('2',r,c), 2 if i in (0,4) else 5)
        elif v==3:
            for i,rr in enumerate(range(r,r+4)):
                mark(rr,c,('3',r,c), 3 if i in (0,3) else 5)
        elif v==6:
            for i,rr in enumerate(range(r-6,r+1)):
                mark(rr,c,('6',r,c), 6 if i in (0,6) else 5)
        elif v==1:
            others=[o for (_,_,o) in cells if o!=1]
            off = 1 if (others and max(others)==2) else 2
            for i,cc in enumerate(range(c,c+3)):
                mark(r,cc,('1',r,c), 1 if i==0 else 5)
            mark(r-1,c+off,('1',r,c), 1)
    beams=[]
    for r in range(h):
        for c in range(w):
            if len(cov[r][c])>=2:
                out[r][c]=4; beams.append((r,c))
    for r,c in beams:
        rr,cc=r,c
        while True:
            rr,cc=rr+1,cc-1
            if rr>=h or cc<0: break
            out[rr][cc]=4
    return out

